CREATE OR REPLACE FUNCTION public.record_legal_acceptance(p_terms_version text, p_privacy_version text, p_accepted_at timestamp with time zone DEFAULT now(), p_source text DEFAULT 'setup_wizard'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_store_id uuid := public.current_store_id();
  v_id uuid;
  v_accepted_at timestamptz := COALESCE(p_accepted_at, now());
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF v_store_id IS NULL THEN
    RAISE EXCEPTION 'No active store is assigned' USING ERRCODE = '22023';
  END IF;
  IF btrim(COALESCE(p_terms_version, '')) = '' OR btrim(COALESCE(p_privacy_version, '')) = '' THEN
    RAISE EXCEPTION 'Policy versions are required' USING ERRCODE = '22023';
  END IF;
  IF p_source NOT IN ('signup', 'setup_wizard', 'policy_update') THEN
    RAISE EXCEPTION 'Invalid legal acceptance source' USING ERRCODE = '22023';
  END IF;
  IF v_accepted_at < now() - interval '24 hours' OR v_accepted_at > now() + interval '5 minutes' THEN
    v_accepted_at := now();
  END IF;

  INSERT INTO public.legal_acceptances
    (user_id, store_id, terms_version, privacy_version, accepted_at, source)
  VALUES
    (v_user_id, v_store_id, btrim(p_terms_version), btrim(p_privacy_version), v_accepted_at, p_source)
  ON CONFLICT (user_id, store_id, terms_version, privacy_version) DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id
    FROM public.legal_acceptances
    WHERE user_id = v_user_id
      AND store_id = v_store_id
      AND terms_version = btrim(p_terms_version)
      AND privacy_version = btrim(p_privacy_version);
  END IF;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_payment_terminals_protect_stripe_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() = 'service_role' OR public.is_platform_staff(auth.uid()) THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.stripe_reader_id IS NOT NULL
       OR NEW.stripe_connected_account_id IS NOT NULL
       OR NEW.stripe_terminal_location_id IS NOT NULL THEN
      RAISE EXCEPTION 'Stripe processor identifiers are server-controlled';
    END IF;
  ELSIF NEW.stripe_reader_id IS DISTINCT FROM OLD.stripe_reader_id
     OR NEW.stripe_connected_account_id IS DISTINCT FROM OLD.stripe_connected_account_id
     OR NEW.stripe_terminal_location_id IS DISTINCT FROM OLD.stripe_terminal_location_id THEN
    RAISE EXCEPTION 'Stripe processor identifiers are server-controlled';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_authenticated_write_rate_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_limit integer := TG_ARGV[0]::integer;
  v_window integer := TG_ARGV[1]::integer;
  v_block integer := TG_ARGV[2]::integer;
  v_key text;
  v_allowed boolean;
  v_remaining integer;
  v_retry integer;
BEGIN
  IF v_actor IS NULL THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  v_key := encode(digest(v_actor::text || ':' || TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME || ':' || TG_OP, 'sha256'),'hex');
  SELECT allowed, remaining, retry_after_seconds INTO v_allowed, v_remaining, v_retry
  FROM public.consume_api_rate_limit(v_key,'db.write.' || TG_TABLE_NAME || '.' || lower(TG_OP),v_limit,v_window,v_block);
  IF NOT COALESCE(v_allowed, false) THEN
    RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='RATE_LIMITED', DETAIL='retry_after_seconds=' || GREATEST(1,COALESCE(v_retry,1));
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

