CREATE OR REPLACE FUNCTION public.tg_enforce_role_exclusivity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_is_new_platform boolean; v_has_merchant boolean; v_has_platform boolean;
BEGIN
  v_is_new_platform := NEW.role::text IN ('super_admin','operations_admin','support_admin','billing_admin','analyst');
  IF v_is_new_platform THEN
    SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=NEW.user_id AND role::text NOT IN ('super_admin','operations_admin','support_admin','billing_admin','analyst')) INTO v_has_merchant;
    IF v_has_merchant THEN RAISE EXCEPTION 'User % already has a merchant role; platform-staff roles cannot be mixed with merchant roles.', NEW.user_id; END IF;
  ELSE
    SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=NEW.user_id AND role::text IN ('super_admin','operations_admin','support_admin','billing_admin','analyst')) INTO v_has_platform;
    IF v_has_platform THEN RAISE EXCEPTION 'User % is platform staff; merchant roles cannot be assigned to platform accounts.', NEW.user_id; END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_protect_super_admin_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_touches_super boolean := false;
BEGIN
  IF TG_OP='INSERT' THEN v_touches_super := NEW.role::text='super_admin';
  ELSIF TG_OP='UPDATE' THEN v_touches_super := NEW.role::text='super_admin' OR OLD.role::text='super_admin';
  ELSIF TG_OP='DELETE' THEN v_touches_super := OLD.role::text='super_admin'; END IF;
  IF v_touches_super AND COALESCE(auth.role(),'') <> 'service_role' AND NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Only platform super admins can manage the super_admin role';
  END IF;
  RETURN COALESCE(NEW,OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_time_entries_compute_late()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sched text; v_threshold int; v_tz text; v_now_local timestamp; v_sched_local timestamp; v_diff_min int;
BEGIN
  SELECT scheduled_start_time, late_threshold_minutes INTO v_sched,v_threshold FROM public.profiles WHERE id=NEW.user_id;
  IF v_sched IS NULL OR v_sched='' THEN RETURN NEW; END IF;
  SELECT COALESCE(time_zone,'UTC') INTO v_tz FROM public.stores WHERE id=NEW.store_id;
  IF v_tz IS NULL THEN v_tz:='UTC'; END IF;
  v_now_local := (NEW.clock_in AT TIME ZONE v_tz);
  v_sched_local := (date_trunc('day',v_now_local) + v_sched::time);
  v_diff_min := EXTRACT(EPOCH FROM (v_now_local-v_sched_local))/60;
  IF v_diff_min > COALESCE(v_threshold,5) THEN NEW.late:=true; NEW.late_minutes:=v_diff_min; END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_user_roles_protect_last_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_store uuid; v_user uuid; v_remaining int;
BEGIN
  IF TG_OP='DELETE' THEN
    IF OLD.role::text <> 'owner' THEN RETURN OLD; END IF;
    v_store:=OLD.store_id; v_user:=OLD.user_id;
  ELSIF TG_OP='UPDATE' THEN
    IF OLD.role::text='owner' AND NEW.role::text <> 'owner' THEN v_store:=OLD.store_id; v_user:=OLD.user_id; ELSE RETURN NEW; END IF;
  ELSE RETURN NEW; END IF;
  SELECT count(*) INTO v_remaining FROM public.user_roles WHERE store_id=v_store AND role='owner'::app_role AND user_id<>v_user;
  IF v_remaining < 1 THEN RAISE EXCEPTION 'Cannot demote or remove the last owner of this business'; END IF;
  RETURN COALESCE(NEW,OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.pos_pin_conflict_check(_store_id uuid, _fingerprint text, _exclude_user uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_current_store uuid;
begin
  if auth.role() = 'service_role' then
    return exists (
      select 1 from public.profiles
      where store_id=_store_id and status='active' and pin_fingerprint=_fingerprint
        and (_exclude_user is null or id<>_exclude_user)
    );
  end if;
  if auth.uid() is null then return false; end if;
  v_current_store := public.current_store_id();
  if _store_id is null or _store_id is distinct from v_current_store then return false; end if;
  if _exclude_user is not null and not exists (
    select 1 from public.profiles where id=_exclude_user and store_id=v_current_store
  ) then return false; end if;
  return exists (
    select 1 from public.profiles
    where store_id=v_current_store and status='active' and pin_fingerprint=_fingerprint
      and (_exclude_user is null or id<>_exclude_user)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.can_manage_employee(_actor uuid, _target uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor_store uuid;
  v_target_store uuid;
  v_actor_roles text[];
  v_target_roles text[];
begin
  if _actor is null or _target is null then return false; end if;
  if auth.role() <> 'service_role' and (_actor is distinct from auth.uid()) then return false; end if;

  select store_id into v_actor_store from public.profiles where id=_actor;
  select store_id into v_target_store from public.profiles where id=_target;
  if v_actor_store is null or v_target_store is null or v_actor_store<>v_target_store then return false; end if;
  if auth.role() <> 'service_role' and v_actor_store is distinct from public.current_store_id() then return false; end if;

  select coalesce(array_agg(role::text),array[]::text[]) into v_actor_roles
    from public.user_roles where user_id=_actor and store_id=v_actor_store;
  select coalesce(array_agg(role::text),array[]::text[]) into v_target_roles
    from public.user_roles where user_id=_target and store_id=v_target_store;

  if v_target_roles && array['super_admin','operations_admin','support_admin','billing_admin','analyst','technical_support','merchant_support','compliance_support','billing_support','read_only_auditor'] then return false; end if;
  if 'owner'=any(v_actor_roles) then return true; end if;
  if 'admin'=any(v_actor_roles) then return not ('owner'=any(v_target_roles)); end if;
  if 'manager'=any(v_actor_roles) then
    if _actor=_target then return false; end if;
    return not ('owner'=any(v_target_roles) or 'admin'=any(v_target_roles) or 'manager'=any(v_target_roles));
  end if;
  return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.has_admin_permission(_user_id uuid, _permission text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if _user_id is null or _permission is null then return false; end if;
  if auth.role() <> 'service_role' and _user_id is distinct from auth.uid() then return false; end if;
  return exists (
    select 1 from public.user_roles ur where ur.user_id=_user_id and ur.role::text='super_admin'
  ) or exists (
    select 1 from public.user_roles ur
    join public.admin_permissions ap on ap.role=ur.role::text
    where ur.user_id=_user_id and (ap.permission=_permission or ap.permission='*')
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.merchant_close_support_ticket(_ticket_id uuid)
 RETURNS support_tickets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_store uuid;
  v_active boolean;
  v_ticket public.support_tickets;
  v_is_priv boolean;
  v_is_requester boolean;
  v_now timestamptz := now();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT store_id, (status = 'active')
    INTO v_store, v_active
  FROM public.profiles
  WHERE id = v_uid;

  IF NOT COALESCE(v_active, false) OR v_store IS NULL THEN
    RAISE EXCEPTION 'Inactive or unassigned employee' USING ERRCODE = '42501';
  END IF;

  SELECT *
    INTO v_ticket
  FROM public.support_tickets
  WHERE id = _ticket_id;

  IF NOT FOUND OR v_ticket.store_id IS DISTINCT FROM v_store THEN
    RAISE EXCEPTION 'Ticket not found' USING ERRCODE = '42501';
  END IF;

  v_is_requester := (v_ticket.requester_id = v_uid);
  v_is_priv :=
    public.has_any_role(v_uid, ARRAY['owner'::app_role, 'admin'::app_role, 'manager'::app_role])
    OR public.has_permission(v_uid, 'support.manage');

  IF NOT (v_is_requester OR v_is_priv) THEN
    RAISE EXCEPTION 'Not permitted to close this ticket' USING ERRCODE = '42501';
  END IF;

  UPDATE public.support_tickets
  SET
    status = 'closed',
    chat_status = 'ended',
    chat_ended_at = COALESCE(chat_ended_at, v_now),
    chat_ended_by = COALESCE(chat_ended_by, v_uid),
    closed_at = COALESCE(closed_at, v_now),
    resolved_at = COALESCE(resolved_at, v_now),
    updated_at = v_now
  WHERE id = _ticket_id
  RETURNING * INTO v_ticket;

  RETURN v_ticket;
END
$function$

CREATE OR REPLACE FUNCTION public.activate_verified_business_trial()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_store_id uuid;
  v_fp text;
  v_days integer := 14;
  v_registry public.business_trial_registry%rowtype;
BEGIN
  IF old.email_confirmed_at IS NOT NULL OR new.email_confirmed_at IS NULL THEN
    RETURN new;
  END IF;

  SELECT p.store_id INTO v_store_id
  FROM public.profiles p
  WHERE p.id = new.id;

  IF v_store_id IS NULL THEN
    RETURN new;
  END IF;

  SELECT s.business_fingerprint INTO v_fp
  FROM public.stores s
  WHERE s.id = v_store_id;

  -- Mark this transaction as an internal platform write before touching
  -- fields protected from merchant-side updates.
  PERFORM set_config('seza.internal_platform_write', 'on', true);

  IF v_fp IS NULL OR v_fp = '' THEN
    UPDATE public.stores
       SET trial_eligibility = 'review',
           business_verification_status = 'review',
           plan_status = 'inactive',
           trial_ends_at = NULL,
           plan_period_end = NULL
     WHERE id = v_store_id;
    PERFORM set_config('seza.internal_platform_write', 'off', true);
    RETURN new;
  END IF;

  SELECT coalesce(default_trial_days, 14)
    INTO v_days
    FROM public.platform_settings
   WHERE id = 'global';

  v_days := coalesce(v_days, 14);

  INSERT INTO public.business_trial_registry (
    business_fingerprint,
    normalized_business_name,
    first_user_id,
    first_store_id
  )
  VALUES (
    v_fp,
    lower(trim(coalesce(new.raw_user_meta_data->>'business_name', 'business'))),
    new.id,
    v_store_id
  )
  ON CONFLICT (business_fingerprint) DO NOTHING;

  SELECT * INTO v_registry
  FROM public.business_trial_registry
  WHERE business_fingerprint = v_fp
  FOR UPDATE;

  IF v_registry.status IN ('trial_used', 'trial_active', 'paid', 'blocked')
     AND v_registry.first_user_id IS DISTINCT FROM new.id THEN
    UPDATE public.stores
       SET trial_eligibility = 'used',
           plan_status = 'inactive',
           trial_ends_at = NULL,
           plan_period_end = NULL
     WHERE id = v_store_id;
    PERFORM set_config('seza.internal_platform_write', 'off', true);
    RETURN new;
  END IF;

  UPDATE public.business_trial_registry
     SET status = 'trial_active',
         first_user_id = coalesce(first_user_id, new.id),
         first_store_id = coalesce(first_store_id, v_store_id),
         trial_started_at = coalesce(trial_started_at, now()),
         trial_ends_at = coalesce(trial_ends_at, now() + make_interval(days => v_days)),
         updated_at = now()
   WHERE business_fingerprint = v_fp;

  UPDATE public.stores
     SET business_verification_status = 'verified',
         trial_eligibility = 'eligible',
         plan_tier = 'trial_pro',
         plan_status = 'trialing',
         trial_ends_at = coalesce(trial_ends_at, now() + make_interval(days => v_days)),
         plan_period_end = coalesce(plan_period_end, now() + make_interval(days => v_days))
   WHERE id = v_store_id;

  PERFORM set_config('seza.internal_platform_write', 'off', true);
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_subscription_recompute()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF OLD.store_id IS DISTINCT FROM NEW.store_id
       OR OLD.environment IS DISTINCT FROM NEW.environment THEN
      IF OLD.store_id IS NOT NULL THEN
        PERFORM public.recompute_store_plan_for_environment(
          OLD.store_id,
          COALESCE(OLD.environment, 'sandbox')
        );
      END IF;
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.store_id IS NOT NULL THEN
      PERFORM public.recompute_store_plan_for_environment(
        OLD.store_id,
        COALESCE(OLD.environment, 'sandbox')
      );
    END IF;
    RETURN NULL;
  END IF;

  IF NEW.store_id IS NOT NULL THEN
    PERFORM public.recompute_store_plan_for_environment(
      NEW.store_id,
      COALESCE(NEW.environment, 'sandbox')
    );
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_protect_card_processing_pricing()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.recover_card_processing_costs IS DISTINCT FROM OLD.recover_card_processing_costs THEN
    IF auth.role() <> 'service_role'
       AND NOT EXISTS (
         SELECT 1
         FROM public.user_roles ur
         WHERE ur.user_id = auth.uid()
           AND ur.store_id = OLD.id
           AND ur.role = 'owner'::public.app_role
       ) THEN
      RAISE EXCEPTION 'Only the business owner can change card-processing cost recovery'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  IF NEW.card_processing_percent IS DISTINCT FROM OLD.card_processing_percent
     OR NEW.card_processing_fixed_fee IS DISTINCT FROM OLD.card_processing_fixed_fee THEN
    IF auth.role() <> 'service_role' THEN
      RAISE EXCEPTION 'Card-processing pricing is managed by SEZA'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
